*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.vScrenID = "ULDSTF08057_new.xml";
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "", scwin.gubun = "", scwin.select_gubun = "";
scwin.trsCnt = 0, scwin.trsTotalCnt = 0, scwin.trsErrCnt = 0;
scwin.selectedGrdNum = 0;
scwin.trsIdx; // insert, update 구분

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_new_onload = function() {
    /* useupdate를 false로 지정함. */
    var url = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=ETN_DELLIST_MST_INOUT";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    //dts_Mst.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELLIST_MST_INOUT";
    dts_Mst.DataID = encodeURI(url);
    dts_Mst.reset();
    dts_Isu.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=CODE_ETN_OUT";
    dts_Isu.reset();
    dts_Isu.insertRow();
    dts_Isu_Temp.DataID = "/etn/EtnMktAct.do?method=searchDelist&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LOSSLMT_EARY_REDMPT + "&TRS_IDX=" + TRS_IDX_NEWSEL + "&GUBUN_CD=" + $c.ut.cGetToday("yyyymmdd");
    //dts_Isu_Temp.DataID = "/etn/EtnMktAct.do?method=searchDelist&DIV_IDX="+DIV_IDX_ETN_DELLIST_DTL+ "&TRS_IDX="+TRS_IDX_NEWSEL + "&GUBUN_CD=" + cGetToday("yyyymmdd") ;

    dts_Isu_Temp.reset();
};
scwin.fn_CheckForm = function() {
    if (dts_Isu_Temp.getTotalRow() == 0) {
        $c.win.alert("[상장폐지종목]을 선택하세요.");
        return false;
    }
    if (!$c.lce.checkDdTm("DD", edt_DelistDd, "상장폐지", false)) return false;
    if (!$c.stf.checkEmptyValue(txb_GrndRegulNm, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txb_GrndRegulNm, 200, "근거규정")) return false;
    if (!$c.stf.checkMaxLength(txa_Remk, 2000, "기타")) return false;
    return true;
};
scwin.fn_dupCheck = function(pUpdate) {
    var delistDate = $c.stf.getObjectValue(edt_DelistDd);
    var isNotDup = true;
    for (var i = 1, j = dts_Isu_Temp.getTotalRow(); i <= j; i++) {
        var isuCd = dts_Isu_Temp.getCellData(i, "ISU_CD");
        var bzProcsNo = dts_Isu_Temp.getCellData(i, "BZ_PROCS_NO");
        var url = "/Delisting.do?method=searchDupDelist" + "&ISU_CD=" + isuCd + "&DELIST_DD=" + delistDate;
        if (pUpdate) url += "&BZ_PROCS_NO=" + bzProcsNo;
        dts_DupIsu.DataID = encodeURI(url);
        dts_DupIsu.reset();
        var dupIsuCd = dts_DupIsu.getCellData(1, "ISU_CD");
        if (dts_DupIsu.getTotalRow() > 0) {
            isNotDup = false;
            $c.win.alert("동일한 날짜에 상장폐지된 종목[" + dupIsuCd + "]이 존재합니다.");
            return false;
        }
    }
    return isNotDup;
};
scwin.fn_copy_dts = function(index) {
    //dts_Isu.Reset();
    if (dts_Isu.getTotalRow() == 0) {
        dts_Isu.insertRow();
    }
    dts_Isu.setCellData(1, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    dts_Isu.setCellData(1, "ISU_CD", dts_Isu_Temp.getCellData(index, "ISU_CD"));
    dts_Isu.setCellData(1, "ISU_NM", dts_Isu_Temp.getCellData(index, "ISU_NM"));
    dts_Isu.setCellData(1, "ISUR_CD", dts_Isu_Temp.getCellData(index, "ISUR_CD"));
    dts_Isu.setCellData(1, "ISUR_NM", dts_Isu_Temp.getCellData(index, "ISUR_NM"));
    dts_Isu.setCellData(1, "COM_NM", dts_Isu_Temp.getCellData(index, "COM_NM"));
    dts_Isu.setCellData(1, "LSTTRD_DD", dts_Isu_Temp.getCellData(index, "LSTTRD_DD"));
    dts_Isu.setCellData(1, "EXP_DD", dts_Isu_Temp.getCellData(index, "EXP_DD"));
    scwin.Isur_cd = dts_Isu_Temp.getCellData(index, "ISUR_CD");
    scwin.Isur_nm = dts_Isu_Temp.getCellData(index, "COM_NM");
};
scwin.fn_save_trs = function() {
    // 종목별 처리를 위해 매번 업무처리 번호를 세팅함
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "ISUR_CD", "99999");

    // 1 : 종목별 , 2 : 법인별
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "MKTACT_APPL_OBJ_TP_CD", "1");
    var vScrenProcsTpCD = SCREN_PROCS_TP_CD_03;
    if (scwin.trsIdx == TRS_IDX_INSERT) vScrenProcsTpCD = SCREN_PROCS_TP_CD_02;

    else if (scwin.trsIdx == TRS_IDX_DELETE) vScrenProcsTpCD = SCREN_PROCS_TP_CD_04;
    trs.Action = $c.lce.fn_encodeNSession("/etn/EtnMktAct.do?method=saveDelist&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + vScrenProcsTpCD);
    trs.KeyName = "toinb_dataid4";
    trs.KeyValue = "JSP(I: dtsParm1= dts_Mst , I:dtsParm2= dts_Isu)";
    trs.Parameters = "TRS_IDX=" + scwin.trsIdx + ",BZ_PROCS_NO=" + scwin.fr_bz_procs_no + ",COUNT=2" + ",LIST_BZ_TP_CD=" + LIST_BZ_TP_CD_706 + // LIST_BZ_TP_CD_715   ETN 조기상환에 의한 상장폐지
        ",DIV_IDX[0]=" + DIV_IDX_ETN_DELLIST_MST + ",DIV_IDX[1]=" + DIV_IDX_ETN_DELLIST_DTL;
    trs.Post();
};
scwin.fn_save = function() {
    if ($c.en.fn_CheckForm() && scwin.fn_dupCheck()) {
        if (!$c.lce.fn_isProcess('I')) return;
        scwin.trsTotalCnt = dts_Isu_Temp.getTotalRow();
        scwin.trsCnt = 0;
        scwin.trsErrCnt = 0;
        for (var i = 1; i <= dts_Isu_Temp.getTotalRow(); i++) {
            scwin.fr_bz_procs_no = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
            scwin.fn_copy_dts(i);
            if (scwin.fr_bz_procs_no.length != 14) {
                $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
            } else {
                scwin.trsIdx = TRS_IDX_INSERT;
                dts_Isu_Temp.setCellData(i, "STATUS", "N");
                scwin.trsCnt++;
                scwin.fn_save_trs();
            }
        }
    }
};
scwin.fn_update = function() {
    if ($c.en.fn_CheckForm() && scwin.fn_dupCheck(true)) {
        scwin.trsIdx = TRS_IDX_UPDATE;
        if (!$c.lce.fn_isProcess('U')) return;
        scwin.trsTotalCnt = dts_Isu_Temp.getTotalRow();
        scwin.trsCnt = 0;
        scwin.trsErrCnt = 0;
        for (var i = 1; i <= dts_Isu_Temp.getTotalRow(); i++) {
            scwin.fr_bz_procs_no = dts_Isu_Temp.getCellData(i, "BZ_PROCS_NO");
            //alert('fr_bz_procs_no : ' + fr_bz_procs_no);

            scwin.fn_copy_dts(i);
            dts_Isu_Temp.setCellData(i, "STATUS", "N");
            scwin.trsCnt++;
            scwin.fn_save_trs();
        }
    }
};
scwin.fn_delete = function() {
    if (!$c.lce.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    scwin.trsTotalCnt = dts_Isu_Temp.getTotalRow();
    scwin.trsCnt = 0;
    scwin.trsErrCnt = 0;
    for (var i = 1; i <= dts_Isu_Temp.getTotalRow(); i++) {
        scwin.fr_bz_procs_no = dts_Isu_Temp.getCellData(i, "BZ_PROCS_NO");
        //alert('fr_bz_procs_no : ' + fr_bz_procs_no);

        scwin.fn_copy_dts(i);
        dts_Isu_Temp.setCellData(i, "STATUS", "N");
        scwin.trsCnt++;
        scwin.fn_save_trs();
    }
};
scwin.fn_dscl = async function() {
    if (scwin.selectedGrdNum == 0) {
        $c.win.alert('종목을 선택해 주세요! ');
        return;
    }
    //alert('selectedGrdNum :: '+ selectedGrdNum );	
    scwin.fn_copy_dts(scwin.selectedGrdNum);
    var OldGet = scwin.fn_GetPar;
    var OldSet = scwin.fn_SetPar;
    dts_Mst.setCellData(dts_Mst.getRowPosition(), "COM_NM", dts_Isu_Temp.getCellData(scwin.selectedGrdNum, "COM_NM"));
    scwin.fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2) {
        arr[0] = "68351";
        arr[1] = scwin.fr_bz_procs_no;
        arr[2] = scwin.Isur_cd;
        arr[3] = '1';
        //arr[4]; //ctnt
        arr[5] = dts_Isu_Temp.getCellData(scwin.selectedGrdNum, "ISU_NM");
        //arr[5] = fn_GetAddTitle(dts_Mst.NameValue(dts_Mst.RowPosition, "COM_NM")); //add  title

        $c.stf.CopyDataSet(dts_Isu, param_dts_isu);
        $c.stf.CopyDataSet(dts_Mst, param_dts_mst);
        param_dts_mst.setCellData(param_dts_mst.getFocusedRowIndex(), "DELIST_RSN_NM", dts_Mst.getCellData(dts_Mst.getRowPosition(), "DELIST_RSN_DSC"));
        return arr.length;
    };
    scwin.fn_SetPar = function(arr) {

    };
    var wth = 730 + 15;
    var hgt = 785 + 40;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    scwin.fn_GetPar = OldGet;
    scwin.fn_SetPar = OldSet;
};
scwin.fn_drft = function() {

};
scwin.fn_makt = function() {

};
scwin.fn_parentRefresh = function() {
    var fr_fn_list_sync = $c.frame.path("../").fn_search3;
    fr_fn_list_sync();
};
scwin.fn_SelectGridRow = function(row) {
    scwin.selectedGrdNum = row;
    scwin.Isur_cd = dts_Isu_Temp.getCellData(row, "ISUR_CD");
    scwin.fr_bz_procs_no = dts_Isu_Temp.getCellData(row, "BZ_PROCS_NO");
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_DelistDd_onclick = function() {
    txa_Remk.Text = "";
    edt_DelistDd.focus();
    popUpCalendar2(edt_DelistDd);
};
scwin.trs_OnFail = function() {
    dts_Isu_Temp.setCellData(scwin.trsCnt, "STATUS", "N");
    scwin.trsErrCnt++;
    if (scwin.trsCnt == scwin.trsTotalCnt && scwin.trsErrCnt > 0) {
        $c.lce.fn_alertMsg('F');
        if (buttonSet.status == "D") {
            // 삭제처리의 응답인 경우
            for (var i = 1; i <= dts_Isu_Temp.getTotalRow(); i++) {
                if (dts_Isu_Temp.getCellData(i, "STATUS") == "Y") {
                    $c.cp.removeRow(dts_Isu_Temp, i);
                }
            }
        } else {

        }
    }
};
scwin.trs_OnSuccess = async function() {
    dts_Isu_Temp.setCellData(scwin.trsCnt, "BZ_PROCS_NO", scwin.fr_bz_procs_no);
    dts_Isu_Temp.setCellData(scwin.trsCnt, "STATUS", "Y");
    if (scwin.trsCnt == scwin.trsTotalCnt) {
        $c.lce.fn_alertMsg('S');
        scwin.fn_parentRefresh(); // 목록 다시 조회

        if (dts_Isu_Temp.getTotalRow() == 1) {
            scwin.fn_SelectGridRow(1);
        }
        if (buttonSet.status == "I") {
            // 저장처리의 응답인 경우
            buttonSet.setUpdateStatus();
            //fn_SetIsuCdBtnShow(1);

        } else if (buttonSet.status == "D") {
            // 삭제처리의 응답인 경우
            await $c.frame.CloseFrame();
        } else {
            //fn_search();

        }
        scwin.selectedGrdNum = 0;
        dts_Isu_Temp.setRowPosition(0, 0);
    }
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.dts_Isu_Temp_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu_Temp);
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {
    dts_Isu.insertRow();
};
scwin.dts_Isu_Temp_OnLoadCompleted = function(rowcount) {
    //if(rowcount > 0) {

    //Isur_cd = dts_Isu.NameString(dts_Isu.RowPosition, "ISUR_CD");

    //if (fr_bz_procs_no == "") {

    //		setObjectValue(edt_DelistDd, cGetPlusDate2(dts_Isu.NameString(dts_Isu.RowPosition, "LSTTRD_DD"),1));

    //	}

    //}

};
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    if (scwin.fr_bz_procs_no == "") {
        dts_Mst.insertRow();
    }

    // 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
    if (scwin.fr_bz_procs_no == "") {
        buttonSet.setInsertStatus();
    } else {
        $c.stf.setButtonSetWithDate(edt_DelistDd, false);
    }
    if (scwin.fr_bz_procs_no == "") {
        dts_Mst.setCellData(dts_Mst.getRowPosition(), "DELIST_RSN_CD", "720021");
        dts_Mst.setCellData(dts_Mst.getRowPosition(), "DELIST_RSN_DSC", "상장지수증권 조기상환 조건 발생");
        dts_Mst.setCellData(dts_Mst.getRowPosition(), "GRND_REGUL_NM", "유가증권시장상장규정 제149조의7");
    }
};
scwin.edt_DelistDd_OnKillFocus = function() {
    //fn_setRemk();

};
scwin.MxGrid_2_OnClick = function(row, colid) {
    scwin.fn_SelectGridRow(row);
};
scwin.gform_onload = function() {
    var fnc = $c.frame.path("../").scwin.fn_GetPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
    var arrPar = new Array();
    if (fnc != undefined) {
        fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
        scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
        scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
        scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
        scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
        scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)
        scwin.gubun = (arrPar.length >= 6 ? arrPar[5] : ""); // 발행사/기초자산 구분값
        scwin.select_gubun = (arrPar.length >= 7 ? arrPar[6] : ""); //  구분값

    }

    //alert( "Isur_cd =  " +Isur_cd + "\n"  + " Isur_nm = " + Isur_nm + "\n" + "  Secugrp_id = " + Secugrp_id + "\n" + 
    //		 "Mkt_id =  " +Mkt_id + "\n" + " fr_bz_procs_no = " + fr_bz_procs_no+ "\n"  ) ;

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성

    //	fn_SetIsuCdBtnShow(select_gubun);
    scwin.fn_new_onload(); // 신규작성시 호출

    $c.libRoundPanel.PanelToGroupBox(panel_3);
};
